-- Promote 문찐 (462), 혼코노 (463), 별다줄 (464), 얼빡 (465), 반모 (466), 웃프다 (467)
-- from slang_candidates (2026-09-11 morning review, operator approved; draft_payload as-is).
-- All six checked against the Standard Korean Language Dictionary: no entry (반모: homonym
-- entries only, different meaning). Each meaning cross-checked against 3-4 independent sources.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('462', '문찐', 'Mun-Jjin', 'new-slang', '유행에 뒤처진 사람 (문화 찐따)', '{"de": "Jemand, der bei Trends nicht mitkommt", "en": "Someone hopelessly out of the loop on trends", "es": "Alguien que no se entera de las modas", "ja": "流行についていけない人", "vi": "Người mù tịt xu hướng"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Kenne nur ich dieses Meme nicht? Ich komme echt nicht mehr mit.", "es": "¿Solo yo no conozco ese meme? Está claro que no me entero de nada.", "ja": "そのミーム知らないの私だけ?完全に流行についていけてないわ。", "vi": "Mỗi tớ không biết meme đó à? Chắc tớ mù xu hướng thật rồi.", "eng": "Am I the only one who doesn''t know that meme? Guess I''m out of the loop.", "kor": "그 밈 나만 몰라? 나 문찐인가 봐."}], "definition": "''문화 찐따''의 줄임말. 최신 유행이나 대중문화를 잘 모르고 못 따라가는 사람. ''찐따''라는 비하어가 들어 있어 남에게 대놓고 쓰면 무례하지만, 실제로는 ''나 완전 문찐이야''처럼 자기를 낮추는 농담으로 훨씬 많이 쓴다.", "definition_i18n": {"de": "Kurz für ''Kultur-Loser'' - jemand, der aktuelle Trends und Popkultur nicht kennt oder nicht mitbekommt. Es enthält das abwertende 찐따, gegen andere gerichtet ist es also unhöflich; tatsächlich sagt man es meist über sich selbst.", "en": "Short for ''culture loser'' - someone who does not know or cannot keep up with current trends and pop culture. It contains the pejorative 찐따, so aiming it at someone else is rude; in practice it is mostly self-deprecating (''I''m such a 문찐'').", "es": "Abreviatura de ''pringado cultural'': quien no se entera ni sigue las modas ni la cultura pop. Lleva dentro el despectivo 찐따, así que soltárselo a otro es grosero; en la práctica se usa sobre todo para reírse de uno mismo.", "ja": "「文化ジンタ(ダサい人)」の略。最新の流行や大衆文化についていけない人。「チンタ」という侮蔑語を含むので他人に向けると失礼だが、実際は「私、完全に文チンだわ」と自虐で使うことがはるかに多い。", "vi": "Viết tắt của ''kẻ mù văn hóa'' - người không biết và không theo kịp xu hướng hay văn hóa đại chúng. Vì chứa từ miệt thị 찐따 nên nói vào mặt người khác là bất lịch sự; thực tế đa phần dùng để tự giễu mình."}}]'::jsonb, '''찐따''(어리숙하고 무리에서 겉도는 사람을 낮춰 부르는 말)에 ''문화''를 붙인 조어. 2018~2019년 학생들 사이에서 퍼졌고 2019년 한국일보가 그 해 신조어로 소개했다. 만든 사람이나 최초 게시물은 확인되지 않는다.', '{"de": "Gebildet aus 문화 (Kultur) und 찐따, einem Schimpfwort für sozial unbeholfene Außenseiter. Verbreitete sich 2018-2019 unter Schülern; die Zeitung Hankook Ilbo kürte es 2019 zum Slangwort des Jahres. Urheber oder Erstposting sind unbekannt.", "en": "Formed by prefixing 문화 (culture) to 찐따, a slur for a socially awkward outsider. It spread among students in 2018-2019 and Hankook Ilbo featured it as slang of the year in 2019; no coiner or first post is documented.", "es": "Formado anteponiendo 문화 (cultura) a 찐따, insulto para el torpe que queda al margen del grupo. Se extendió entre estudiantes en 2018-2019 y el diario Hankook Ilbo lo destacó como jerga del año en 2019; no consta autor ni publicación original.", "ja": "「チンタ」(不器用で集団から浮いた人を蔑む語)に「文化」を付けた造語。2018~19年に学生の間で広まり、2019年に韓国日報がその年の新造語として紹介した。造語者や初出の投稿は不明。", "vi": "Ghép 문화 (văn hóa) với 찐따, từ miệt thị người vụng về bị lạc khỏi nhóm. Lan trong học sinh 2018-2019 và báo Hankook Ilbo giới thiệu là tiếng lóng của năm 2019; không rõ ai đặt ra hay bài đăng đầu tiên."}'::jsonb, '남에게 쓰면 비하가 되므로 자조적으로 쓰는 게 안전하다. 학습자라면 ''나 문찐이라 이거 몰라''처럼 자기 얘기에만 쓰길 권한다.', '{"de": "Gegen andere gerichtet ist es eine Beleidigung - also nur über sich selbst sagen. Lernenden empfiehlt sich: ''Ich bin ein 문찐, das kenne ich nicht.''", "en": "Aimed at others it is an insult, so keep it self-directed. Learners are safest saying it only about themselves: ''I''m a 문찐, I don''t know this one.''", "es": "Dirigido a otros es un insulto, así que úsalo solo sobre ti. Para estudiantes, lo seguro es decir ''soy un 문찐, no conozco esto''.", "ja": "他人に向けると侮辱になるので、自虐で使うのが安全。学習者は「私、文チンだからこれ知らない」のように自分のことにだけ使うのがおすすめ。", "vi": "Nói về người khác là xúc phạm, nên chỉ dùng để tự giễu. Người học nên chỉ nói về mình: ''tớ mù xu hướng nên không biết cái này''."}'::jsonb, array['인싸','아싸','핵인싸'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Out of the loop / culturally clueless"}, {"lang": "🇯🇵 JA", "text": "流行に疎い人"}, {"lang": "🇨🇳 ZH", "text": "跟不上潮流的人"}, {"lang": "🇻🇳 VI", "text": "Người mù xu hướng"}, {"lang": "🇪🇸 ES", "text": "Desconectado de las modas"}, {"lang": "🇩🇪 DE", "text": "Trend-Muffel"}]'::jsonb),
('463', '혼코노', 'Hon-Ko-No', 'new-slang', '혼자 코인노래방 가기', '{"de": "Allein ins Münz-Karaoke", "en": "Going to coin karaoke alone", "es": "Ir solo al karaoke de monedas", "ja": "ひとりコインカラオケ", "vi": "Đi hát karaoke xu một mình"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Harter Tag, also war ich allein im Münz-Karaoke.", "es": "Día duro, así que me fui sola al karaoke de monedas.", "ja": "今日ストレスたまったから、ひとりコインカラオケ行ってきた。", "vi": "Hôm nay căng thẳng quá nên tớ đi hát karaoke xu một mình.", "eng": "Rough day, so I went and did solo coin karaoke.", "kor": "오늘 스트레스 받아서 혼코노 갔다 왔어."}], "definition": "''혼자 코인노래방''의 줄임말. 동전을 넣고 부른 곡 수만큼 계산하는 코인노래방에 혼자 가는 것. 혼밥·혼술처럼 ''혼자 하는 여가'' 문화의 하나로, 돈이 거의 안 들면서 스트레스를 푸는 대표적인 혼자 놀이다.", "definition_i18n": {"de": "Kurz für ''Münz-Karaoke allein'' - man geht allein in eine Kabine, wirft Münzen ein und zahlt pro Lied. Gehört zur selben Solo-Freizeitkultur wie allein essen oder trinken und ist eine der billigsten Arten, Dampf abzulassen.", "en": "Short for ''solo coin karaoke'' - going alone to a booth where you drop coins and pay per song. Part of the same solo-leisure culture as eating or drinking alone, and one of the cheapest ways Koreans blow off steam by themselves.", "es": "Abreviatura de ''karaoke de monedas en solitario'': ir solo a una cabina donde metes monedas y pagas por canción. Pertenece a la misma cultura del ocio en solitario que comer o beber solo, y es de las formas más baratas de desahogarse.", "ja": "「ひとりコインカラオケ」の略。コインを入れて歌った曲数だけ払うカラオケにひとりで行くこと。ひとり飯・ひとり酒と同じ「おひとりさま」文化の一つで、ほぼお金をかけずにストレスを発散できる代表的な遊び方。", "vi": "Viết tắt của ''karaoke xu một mình'' - đi một mình tới buồng hát, bỏ xu và trả tiền theo số bài. Cùng dòng văn hóa giải trí một mình như ăn một mình, uống một mình, và là cách xả stress rẻ nhất."}}]'::jsonb, '2010년대 중반 코인노래방이 전국에 퍼지면서 생긴 말. 2010년대 초 ''혼밥''에서 시작된 ''혼+X'' 조어 계열의 하나이고, 최초 사용자는 확인되지 않는다. 영문 위키백과도 한국의 ''혼족(honjok)'' 문화 항목에서 이 말을 다룬다.', '{"de": "Entstand Mitte der 2010er, als sich Münz-Karaoke-Kabinen im ganzen Land ausbreiteten, nach dem Muster 혼+X, das mit 혼밥 (allein essen) Anfang der 2010er begann. Ein erster Nutzer ist nicht belegt; die englische Wikipedia behandelt den Begriff unter Koreas Honjok-Kultur.", "en": "Born in the mid-2010s as coin karaoke booths spread nationwide, following the 혼+X coinage pattern that started with 혼밥 (eating alone) in the early 2010s. No first user is documented; English Wikipedia covers the term under Korea''s honjok culture.", "es": "Surgió a mediados de los 2010 con la expansión de las cabinas de karaoke de monedas, siguiendo el patrón 혼+X que arrancó con 혼밥 (comer solo) a principios de la década. No consta el primer usuario; la Wikipedia inglesa lo recoge dentro de la cultura honjok.", "ja": "2010年代半ばにコインカラオケが全国に広まって生まれた語。2010年代初頭の「ひとり飯」から続く「ひとり+X」造語系の一つ。初使用者は不明で、英語版ウィキペディアも韓国の「ホンジョク」文化の項で扱う。", "vi": "Ra đời giữa thập niên 2010 khi buồng karaoke xu mọc khắp nơi, theo lối ghép 혼+X bắt đầu từ 혼밥 (ăn một mình) đầu thập niên. Không rõ ai dùng đầu tiên; Wikipedia tiếng Anh xếp từ này vào văn hóa honjok của Hàn Quốc."}'::jsonb, '''혼코노 하다'', ''혼코노 가다'' 형태로 쓴다. 예전엔 혼자 노래방 가는 걸 민망해했지만 지금은 당당한 취미로 여겨져, 부끄러움 없이 얘기한다.', '{"de": "Wird als 혼코노 하다 / 혼코노 가다 (machen / gehen) verwendet. Früher war es peinlich, allein ins Karaoke zu gehen; heute ist es ein völlig normales Hobby, von dem man offen erzählt.", "en": "Used as 혼코노 하다 / 혼코노 가다 (to do / to go). Going to karaoke alone used to be embarrassing; now it is a perfectly respectable hobby people mention freely.", "es": "Se usa como 혼코노 하다 / 혼코노 가다 (hacer / ir). Antes daba vergüenza ir solo al karaoke; hoy es una afición respetable que se cuenta sin reparos.", "ja": "「ひとりコインカラオケする・行く」の形で使う。昔はひとりでカラオケに行くのは気まずいこととされたが、今は堂々とした趣味として普通に話す。", "vi": "Dùng ở dạng 혼코노 하다 / 혼코노 가다 (đi / làm). Trước kia đi karaoke một mình thì ngại, giờ là sở thích đàng hoàng ai cũng kể thoải mái."}'::jsonb, array['혼밥','혼술','소확행'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Solo coin karaoke"}, {"lang": "🇯🇵 JA", "text": "ひとりコインカラオケ"}, {"lang": "🇨🇳 ZH", "text": "一个人去投币KTV"}, {"lang": "🇻🇳 VI", "text": "Hát karaoke xu một mình"}, {"lang": "🇪🇸 ES", "text": "Karaoke de monedas en solitario"}, {"lang": "🇩🇪 DE", "text": "Allein ins Münz-Karaoke"}]'::jsonb),
('464', '별다줄', 'Byeol-Da-Jul', 'new-slang', '별걸 다 줄인다 - 과한 줄임말을 비꼬는 말', '{"de": "Alles wird abgekürzt - ein Seitenhieb auf die Abkürzungsmanie", "en": "Everything gets abbreviated - a jab at Korea''s abbreviation habit", "es": "Abrevian hasta lo impensable - burla del exceso de abreviaturas", "ja": "何でも略す - 過剰な略語文化を皮肉る言葉", "vi": "Cái gì cũng viết tắt - câu châm biếm thói viết tắt"}'::jsonb, null, '[{"type": "감탄사", "examples": [{"de": "Was soll ''Aljaldakkalsen''... ihr kürzt echt alles ab.", "es": "¿Qué es ''aljaldakkalsen''...? De verdad que abrevian hasta lo impensable.", "ja": "「アルジャルタッカルセン」って何…ほんと何でも略すな。", "vi": "''Aljaldakkalsen'' là cái gì vậy... đúng là cái gì cũng viết tắt.", "eng": "What even is ''aljaldakkalsen''... you people abbreviate literally everything.", "kor": "''알잘딱깔센''이 뭐야... 진짜 별다줄이다."}], "definition": "''별걸 다 줄인다''의 줄임말. 굳이 줄일 필요 없는 말까지 줄여 쓰는 걸 봤을 때 어이없다는 듯 내뱉는다. 줄임말을 비꼬는 말 자체가 줄임말이라는 게 이 말의 핵심 유머다.", "definition_i18n": {"de": "Kurz für ''die kürzen wirklich alles ab''. Sagt man halb verblüfft, halb genervt, wenn jemand etwas abkürzt, das keiner Abkürzung bedurfte - und die Beschwerde ist selbst eine Abkürzung.", "en": "Short for ''they abbreviate literally everything''. You say it, half amazed and half exasperated, when someone shortens a phrase that did not need shortening - and the joke is that the complaint is itself an abbreviation.", "es": "Abreviatura de ''abrevian hasta lo impensable''. Se suelta entre el asombro y el hartazgo cuando alguien acorta algo que no hacía falta acortar; la gracia es que la queja también es una abreviatura.", "ja": "「別件まで全部略す」の略。略す必要のない言葉まで縮めているのを見たとき、あきれ半分で口にする。略語を皮肉る言葉自体が略語なのが笑いどころ。", "vi": "Viết tắt của ''cái gì cũng viết tắt''. Nói ra nửa ngỡ ngàng nửa ngán ngẩm khi ai đó rút gọn cả những cụm chẳng cần rút gọn - và chính lời than đó cũng là một từ viết tắt."}}]'::jsonb, '2010년대 중후반 학생들 사이에서 줄임말이 폭증하자 이를 받아치려고 만들어진 말. 나무위키는 ''필요 이상으로 줄여 말하는 유행을 카운터치기 위한 용어''로 설명한다. 최초 발화자나 최초 출처는 확인되지 않는다.', '{"de": "Ende der 2010er als Konter auf die Abkürzungsflut unter Schülern entstanden; namu.wiki beschreibt es als Begriff gegen die Angewohnheit, alles über Gebühr zu kürzen. Erster Sprecher oder Erstbeleg sind nicht dokumentiert.", "en": "Coined in the late 2010s as a counterpunch to the explosion of student abbreviations; namu.wiki describes it as a term made to counter the habit of shortening things past necessity. No first speaker or first source is documented.", "es": "Acuñado a finales de los 2010 como réplica a la explosión de abreviaturas estudiantiles; namu.wiki lo describe como un término para contrarrestar el hábito de acortar más de la cuenta. No hay primer hablante ni fuente original documentada.", "ja": "2010年代後半、学生の間で略語が急増したことへの反撃として生まれた語。ナムウィキは「必要以上に略す流行をカウンターするための用語」と説明する。初出や最初の話者は不明。", "vi": "Ra đời cuối thập niên 2010 như đòn phản công trước làn sóng viết tắt của học sinh; namu.wiki mô tả đây là từ dùng để đối lại thói rút gọn quá đà. Không rõ người dùng đầu tiên hay nguồn gốc đầu tiên."}'::jsonb, '누가 처음 보는 줄임말을 썼을 때 감탄 반 핀잔 반으로 쓴다. 어른이 젊은 세대 말투를 지적할 때도, 또래끼리 장난칠 때도 쓴다. 진지한 비판이라기보다 가벼운 농담에 가깝다.', '{"de": "Sagt man, wenn jemand eine nie gehörte Abkürzung fallen lässt - halb bewundernd, halb stichelnd. Passt, wenn Ältere Jugendsprache aufs Korn nehmen und wenn Freunde sich necken; ein Scherz, keine echte Kritik.", "en": "Used when someone drops an abbreviation you have never seen, half in awe and half as a gentle dig. Works both when older people poke at younger slang and when friends tease each other - it is a joke, not a real criticism.", "es": "Se usa cuando alguien suelta una abreviatura que nunca habías visto, mitad admiración mitad pulla. Vale tanto si un adulto pincha la jerga joven como si los amigos se chinchan; es broma, no crítica seria.", "ja": "初めて見る略語を誰かが使ったとき、感心半分・小言半分で使う。大人が若者言葉を突っ込むときも、同年代がふざけるときも使える。本気の批判ではなく軽い冗談。", "vi": "Dùng khi ai đó thốt ra một từ viết tắt bạn chưa từng thấy, nửa thán phục nửa trêu. Người lớn châm chọc tiếng lóng giới trẻ hay bạn bè đùa nhau đều dùng được - là đùa, không phải chê thật."}'::jsonb, array['할많하않','만반잘부','알잘딱깔센'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Y''all abbreviate everything"}, {"lang": "🇯🇵 JA", "text": "何でも略すな"}, {"lang": "🇨🇳 ZH", "text": "什么都要缩写"}, {"lang": "🇻🇳 VI", "text": "Cái gì cũng viết tắt"}, {"lang": "🇪🇸 ES", "text": "Abrevian todo"}, {"lang": "🇩🇪 DE", "text": "Ihr kürzt echt alles ab"}]'::jsonb),
('465', '얼빡', 'Eol-Ppak', 'new-slang', '얼굴을 꽉 채운 클로즈업 샷', '{"de": "Extreme Nahaufnahme, die das Bild mit dem Gesicht füllt", "en": "An extreme close-up that fills the frame with a face", "es": "Un primerísimo plano que llena la pantalla de cara", "ja": "顔で画面を埋めるドアップ", "vi": "Ảnh cận mặt kín cả khung hình"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Unnie, poste bitte wenigstens eine Nahaufnahme!", "es": "¡Unnie, sube aunque sea un primer plano!", "ja": "オンニ、ドアップ写真1枚だけ上げてください!", "vi": "Chị ơi, đăng cho em một tấm cận mặt thôi!", "eng": "Unnie, please post just one close-up!", "kor": "언니 얼빡샷 하나만 올려줘요!"}], "definition": "''얼굴이 빡빡하게 (화면을) 채운다''를 줄인 말. 여백 없이 얼굴만 크게 잡은 사진이나 영상. 보통 ''얼빡샷'', ''얼빡직캠''처럼 뒤에 말을 붙여 쓴다.", "definition_i18n": {"de": "Kurz für ''das Gesicht füllt den Rahmen randlos'' - ein Foto oder Video, so eng beschnitten, dass nur das Gesicht bleibt. Meist zusammengesetzt: 얼빡샷 (Close-up) oder 얼빡직캠 (Close-up-Fancam).", "en": "Short for ''the face packs the frame tight'' - a photo or video cropped so close that nothing but the face is left. Usually compounded, as in 얼빡샷 (close-up shot) or 얼빡직캠 (close-up fancam).", "es": "Abreviatura de ''la cara llena el encuadre a tope'': foto o vídeo recortado tan cerca que solo queda el rostro. Suele ir compuesto: 얼빡샷 (primer plano) o 얼빡직캠 (fancam en primer plano).", "ja": "「顔が画面をぎっしり埋める」の略。余白なく顔だけを大きく捉えた写真や動画。普通は「オルパクショット」「オルパク直カム」のように後ろに語を付けて使う。", "vi": "Viết tắt của ''khuôn mặt lấp kín khung hình'' - ảnh hoặc video cắt sát đến mức chỉ còn gương mặt. Thường ghép thêm, như 얼빡샷 (ảnh cận) hay 얼빡직캠 (fancam cận)."}}]'::jsonb, '''얼굴''의 ''얼''에 ''빡빡하다''의 ''빡''을 붙인 말. 아이돌 팬덤에서 직캠과 셀카를 부르던 표현이 2018년 전후 일반 SNS로 퍼졌다. 최초 사용 팬덤이나 게시물은 확인되지 않는다.', '{"de": "Gebildet aus 얼 (von 얼굴, Gesicht) und 빡 (von 빡빡하다, dicht gepackt). Ursprünglich Idol-Fandom-Vokabular für Fancams und Selfies, um 2018 in die allgemeinen sozialen Medien übergegangen; Ursprungsfandom oder Erstposting sind unbekannt.", "en": "Built from 얼 (from 얼굴, face) plus 빡 (from 빡빡하다, packed tight). It started as idol-fandom vocabulary for fancams and selfies and spread to general social media around 2018; the originating fandom or post is undocumented.", "es": "Formado con 얼 (de 얼굴, cara) y 빡 (de 빡빡하다, apretado). Nació como vocabulario del fandom idol para fancams y selfies y saltó a las redes generales hacia 2018; no consta el fandom ni la publicación original.", "ja": "「顔(オルグル)」の「オル」に「ぎっしり(パクパカダ)」の「パク」を付けた語。アイドルのファンダムで直カムやセルカを指す言葉だったのが2018年前後に一般SNSへ広まった。最初のファンダムや投稿は不明。", "vi": "Ghép 얼 (từ 얼굴, khuôn mặt) với 빡 (từ 빡빡하다, chật kín). Vốn là từ của fandom idol chỉ fancam và ảnh tự chụp, lan ra mạng xã hội phổ thông khoảng 2018; không rõ fandom hay bài đăng đầu tiên."}'::jsonb, '팬이 최애에게 요청할 때, 또는 셀카를 올리며 ''얼빡 주의''처럼 쓴다. 화질과 표정이 그대로 드러나는 각도라 자신 있을 때 올린다는 뉘앙스가 붙는다.', '{"de": "Fans wünschen es sich von ihrem Bias, oder man betitelt das eigene Selfie mit ''얼빡 주의'' (Achtung, Nahaufnahme). Der Winkel verbirgt nichts - wer eines postet, fühlt sich sichtlich sicher.", "en": "Fans request it from their bias, or you caption your own selfie ''얼빡 주의'' (close-up warning). Because the angle hides nothing, posting one implies you are feeling confident.", "es": "Los fans se lo piden a su bias, o uno etiqueta su propio selfie con ''얼빡 주의'' (aviso de primer plano). Como el ángulo no esconde nada, publicarlo implica que te sientes con confianza.", "ja": "ファンが推しにリクエストしたり、自撮りを上げるとき「オルパク注意」と添えたりする。粗も表情もそのまま出る角度なので、自信があるときに上げるニュアンスが伴う。", "vi": "Fan xin idol của mình, hoặc tự chú thích ảnh selfie là ''얼빡 주의'' (cảnh báo ảnh cận). Góc này chẳng giấu được gì nên đăng lên nghĩa là đang tự tin."}'::jsonb, array['직캠','인생샷','최애'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Extreme close-up shot"}, {"lang": "🇯🇵 JA", "text": "顔ドアップ"}, {"lang": "🇨🇳 ZH", "text": "大头特写"}, {"lang": "🇻🇳 VI", "text": "Ảnh cận mặt"}, {"lang": "🇪🇸 ES", "text": "Primerísimo plano"}, {"lang": "🇩🇪 DE", "text": "Gesichts-Nahaufnahme"}]'::jsonb),
('466', '반모', 'Ban-Mo', 'new-slang', '반말 모드 - 서로 말 놓기', '{"de": "Du-Modus - gemeinsam die Höflichkeitsform ablegen", "en": "Casual-speech mode - dropping honorifics together", "es": "Modo tuteo - dejar el lenguaje formal", "ja": "タメ口モード - 敬語をやめて話すこと", "vi": "Chế độ nói trống - bỏ kính ngữ với nhau"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Wir sind gleich alt - wollen wir uns duzen?", "es": "Tenemos la misma edad, ¿nos tuteamos?", "ja": "同い年だし、タメ口で話さない?", "vi": "Mình bằng tuổi mà, nói trống với nhau nhé?", "eng": "We''re the same age - want to just drop the formal speech?", "kor": "우리 나이도 같은데 반모할래?"}], "definition": "''반말 모드''의 줄임말. 온라인에서 처음 만난 사이라도 존댓말을 그만두고 서로 말을 놓자는 것. 먼저 ''반신''(반말 모드 신청)을 하고 상대가 받아주면 반모가 시작된다. 아주 친해지고 싶으면 ''평반''(평생 반말 모드)이나 ''죽반''(죽어도 반말 모드)을 걸기도 한다.", "definition_i18n": {"de": "Kurz für ''Du-Modus'' - die Absprache, mit jemandem, den man gerade online kennengelernt hat, die Höflichkeitsform fallen zu lassen. Zuerst schickt man ein 반신 (Antrag auf Du-Modus); nimmt das Gegenüber an, gilt 반모. Für mehr Nähe gibt es 평반 (Du-Modus fürs Leben) oder 죽반 (Du-Modus bis zum Tod).", "en": "Short for ''casual-speech mode'' - agreeing to drop honorifics with someone you just met online. You first send a 반신 (a request for casual mode); if they accept, 반모 is on. For extra closeness people propose 평반 (casual mode for life) or 죽반 (casual mode till death).", "es": "Abreviatura de ''modo tuteo'': acordar dejar el lenguaje formal con alguien que acabas de conocer en línea. Primero se manda un 반신 (solicitud de modo informal); si acepta, empieza el 반모. Para más cercanía se propone 평반 (tuteo de por vida) o 죽반 (tuteo hasta la muerte).", "ja": "「タメ口モード」の略。ネットで初対面でも敬語をやめて互いにタメ口で話そうということ。まず「パンシン(タメ口モード申請)」を送り、相手が受ければ開始。もっと仲良くなりたければ「ピョンバン(一生タメ口)」「チュクバン(死んでもタメ口)」を申し込む。", "vi": "Viết tắt của ''chế độ nói trống'' - thỏa thuận bỏ kính ngữ với người vừa quen trên mạng. Trước hết gửi 반신 (lời xin nói trống); đối phương đồng ý thì 반모 bắt đầu. Muốn thân hơn thì rủ 평반 (nói trống trọn đời) hay 죽반 (nói trống tới chết)."}}]'::jsonb, '카카오톡 오픈채팅이나 게임 채팅처럼 나이를 모른 채 만나는 익명 공간에서, 존댓말 때문에 거리가 생기는 걸 건너뛰려고 생긴 말. 2010년대 후반 초중고생 사이에서 자리 잡았고 2021년 서울경제 신조어 사전 등에 소개됐다. 최초 사용처는 확인되지 않는다.', '{"de": "Entstand in anonymen Räumen - KakaoTalk-Open-Chats, Game-Lobbys -, wo man sich ohne Altersangabe begegnet und die Höflichkeitsform auf Distanz hält. Setzte sich Ende der 2010er unter Schülern durch und wurde 2021 etwa in der Slang-Kolumne des Seoul Economic Daily behandelt. Der Erstbeleg fehlt.", "en": "Born in anonymous spaces - KakaoTalk open chats, game lobbies - where you meet without knowing anyone''s age and honorifics keep people at arm''s length. It took hold among school-age users in the late 2010s and was written up in outlets such as Seoul Economic Daily''s slang column in 2021. The first use is undocumented.", "es": "Nació en espacios anónimos - chats abiertos de KakaoTalk, salas de juego - donde te conoces sin saber la edad y el lenguaje formal impone distancia. Se asentó entre escolares a finales de los 2010 y lo recogió la columna de jerga del Seoul Economic Daily en 2021. No consta el primer uso.", "ja": "カカオトークのオープンチャットやゲームチャットなど、年齢もわからない匿名空間で敬語が壁になるのを飛ばすために生まれた語。2010年代後半に小中高生の間で定着し、2021年にソウル経済の新造語辞典などで紹介された。初出は不明。", "vi": "Ra đời trong các không gian ẩn danh - chat mở KakaoTalk, phòng game - nơi người ta gặp nhau mà không biết tuổi, còn kính ngữ thì tạo khoảng cách. Phổ biến trong học sinh cuối thập niên 2010, được mục từ mới của báo Seoul Economic Daily giới thiệu năm 2021. Không rõ lần dùng đầu tiên."}'::jsonb, '10대 온라인 대화에서 주로 쓴다. 성인끼리는 반모라고 하지 않고 ''말 놓을까요?''라고 하는 게 보통이니, 학습자는 뜻만 알아두고 실제로는 상대 나이와 상황을 확인한 뒤 쓰는 게 안전하다.', '{"de": "Vor allem Online-Sprache Jugendlicher. Erwachsene sagen eher 말 놓을까요? (''Wollen wir uns duzen?''), Lernende sollten das Wort also kennen, vor dem Gebrauch aber Alter und Situation prüfen.", "en": "Mostly teen online talk. Adults say 말 놓을까요? (''shall we drop the formal speech?'') instead, so learners should know the word but check the other person''s age and the setting before using it.", "es": "Sobre todo en conversaciones adolescentes en línea. Entre adultos se dice 말 놓을까요? (''¿nos tuteamos?''), así que conviene conocer la palabra pero comprobar edad y contexto antes de usarla.", "ja": "主に10代のネット会話で使う。大人同士は「パンモ」ではなく「말 놓을까요?(タメ口にしましょうか)」と言うのが普通なので、学習者は意味だけ覚え、相手の年齢と状況を確かめてから使うのが安全。", "vi": "Chủ yếu trong trò chuyện trực tuyến của tuổi teen. Người lớn nói 말 놓을까요? (''mình nói trống nhé?'') thay vì 반모, nên người học chỉ cần biết nghĩa và kiểm tra tuổi, hoàn cảnh trước khi dùng."}'::jsonb, array['만반잘부','인만추','친목'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Casual-speech mode"}, {"lang": "🇯🇵 JA", "text": "タメ口モード"}, {"lang": "🇨🇳 ZH", "text": "平语模式"}, {"lang": "🇻🇳 VI", "text": "Chế độ nói trống"}, {"lang": "🇪🇸 ES", "text": "Modo tuteo"}, {"lang": "🇩🇪 DE", "text": "Du-Modus"}]'::jsonb),
('467', '웃프다', 'Ut-Peu-Da', 'new-slang', '웃긴데 슬프다', '{"de": "Lustig und traurig zugleich", "en": "Funny and sad at the same time", "es": "Da risa y pena a la vez", "ja": "笑えるのに切ない", "vi": "Vừa buồn cười vừa buồn"}'::jsonb, '[욷프다]', '[{"type": "형용사", "examples": [{"de": "Das Gehalt kam und ging am selben Tag für die Kreditkarte drauf ... lustig, aber es tut weh.", "es": "Me entró el sueldo y se fue el mismo día con la tarjeta... da risa y pena.", "ja": "給料が入った瞬間カードの支払いで全部消えた…笑えるけど切ない。", "vi": "Lương vừa về đã bay sạch vì trả thẻ tín dụng... buồn cười mà buồn thật.", "eng": "My paycheck landed and left the same day for the credit card bill... funny, but it hurts.", "kor": "월급 들어오자마자 카드값으로 다 나갔다... 웃프다."}], "definition": "''웃기다''와 ''슬프다''를 합친 말. 겉으로는 웃음이 나지만 사정을 알고 보면 서글픈 상태. 영어의 tragicomic과 거의 같은 감정이고, 남 얘기보다 자기 처지에 훨씬 자주 쓴다.", "definition_i18n": {"de": "Eine Mischung aus 웃기다 (lustig) und 슬프다 (traurig): Es bringt einen zum Lachen, doch die Lage dahinter schmerzt. Fast genau das Gefühl von tragikomisch - und meist auf das eigene Leben gemünzt.", "en": "A blend of 웃기다 (funny) and 슬프다 (sad): it makes you laugh on the surface, but the situation behind it stings. Almost exactly the feeling of tragicomic, and far more often aimed at your own life than at someone else''s.", "es": "Mezcla de 웃기다 (gracioso) y 슬프다 (triste): por fuera da risa, pero al saber la situación duele. Es casi exactamente lo tragicómico, y se aplica mucho más a la propia vida que a la ajena.", "ja": "「おかしい」と「悲しい」を合わせた語。表面上は笑えるが、事情を知ると切ない状態。英語のtragicomicとほぼ同じ感情で、他人よりも自分の境遇について使うことが圧倒的に多い。", "vi": "Ghép 웃기다 (buồn cười) và 슬프다 (buồn): nhìn thì bật cười nhưng biết hoàn cảnh rồi lại thấy chạnh lòng. Gần đúng cảm giác bi hài, và thường dùng cho chính mình hơn là cho người khác."}}]'::jsonb, '''웃기다 + 슬프다'' 혼성어로 2000년대 후반~2010년대 초 온라인에서 자리 잡았다. 지금은 신조어라기보다 거의 일상어가 되어 위키백과의 인터넷 신조어 목록에도 표제어로 올라 있다. 처음 만든 사람은 확인되지 않는다.', '{"de": "Ein Kofferwort aus 웃기다 und 슬프다, das sich zwischen den späten 2000ern und frühen 2010ern im koreanischen Netz etablierte. Heute eher Alltagswort als Slang und als Stichwort in Wikipedias Liste koreanischer Internet-Neologismen geführt. Ein Urheber ist nicht belegt.", "en": "A portmanteau of 웃기다 and 슬프다 that settled into online Korean between the late 2000s and early 2010s. It is now closer to everyday vocabulary than to slang, and appears as a headword in Wikipedia''s list of Korean internet neologisms. No coiner is documented.", "es": "Palabra maleta de 웃기다 y 슬프다 que se asentó en el coreano en línea entre finales de los 2000 y principios de los 2010. Hoy es más vocabulario cotidiano que jerga y figura como entrada en la lista de neologismos de internet de Wikipedia. No consta autor.", "ja": "「笑える+悲しい」の混成語で、2000年代後半~2010年代初頭にネット上で定着。今では新造語というより日常語に近く、ウィキペディアの韓国インターネット新造語一覧にも見出し語として載る。造語者は不明。", "vi": "Từ ghép pha giữa 웃기다 và 슬프다, định hình trên mạng từ cuối thập niên 2000 đến đầu 2010. Nay gần như từ thông dụng hơn là tiếng lóng, và có mục từ trong danh sách từ mới Internet của Wikipedia. Không rõ ai đặt ra."}'::jsonb, '''웃프다'', ''웃픈 상황'', ''웃프네'' 형태로 쓴다. 자기 처지를 자조할 때 가장 많이 쓰고, 남의 불행에 쓰면 비웃는 것처럼 들릴 수 있으니 조심한다.', '{"de": "Wird als 웃프다 / 웃픈 상황 (tragikomische Lage) / 웃프네 verwendet. Meist selbstironisch; auf fremdes Unglück gemünzt klingt es schnell nach Auslachen.", "en": "Used as 웃프다 / 웃픈 상황 (a tragicomic situation) / 웃프네. Mostly self-deprecating; pointing it at someone else''s misfortune can sound like you are laughing at them.", "es": "Se usa como 웃프다 / 웃픈 상황 (situación tragicómica) / 웃프네. Casi siempre sobre uno mismo; aplicarlo a la desgracia ajena puede sonar a burla.", "ja": "「ウップダ」「ウップン状況」「ウップネ」の形で使う。自虐で使うのが大半で、他人の不幸に使うと嘲笑に聞こえかねないので注意。", "vi": "Dùng ở dạng 웃프다 / 웃픈 상황 (tình huống bi hài) / 웃프네. Chủ yếu để tự giễu; nói về bất hạnh của người khác dễ nghe như đang cười nhạo."}'::jsonb, array['이생망','현타','웃음벨'], array[]::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Tragicomic / funny but sad"}, {"lang": "🇯🇵 JA", "text": "笑えるけど切ない"}, {"lang": "🇨🇳 ZH", "text": "又好笑又心酸"}, {"lang": "🇻🇳 VI", "text": "Buồn cười mà chua chát"}, {"lang": "🇪🇸 ES", "text": "Tragicómico"}, {"lang": "🇩🇪 DE", "text": "Tragikomisch"}]'::jsonb);

